// === Tab: mySketch ===
let sh;
let gra;
let url = "https://coolors.co/app/8fc93a-067bc2-8f2d56-eb5440-ffba49";
let cols;


function setup() {
	createCanvas(windowWidth, screen.availHeight,WEBGL);
	gra = createGraphics(width,height);
	sh = createShader(vert,frag);
	this.shader(sh);
	rectMode(CENTER);
	window.simulatedMouseX = width / 2;
	window.simulatedMouseY = height / 2;
	cols = createCols(url);
	drawgra();
}

function draw() {
	//if(frameCount%240 == 0)drawgra();
	sh.setUniform("u_resolution", [width*2,height*2]);
	sh.setUniform("u_mouse",[(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))*2,(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))*2]);
	sh.setUniform("u_time", millis()*0.002);
	sh.setUniform("u_img",gra);
	noStroke();
	rect(0,0,width,height);
}


function drawgra(){
	gra.background(cols[Math.floor(random(cols.length))]);
	gra.ellipseMode(CENTER);
	gra.rectMode(CENTER);
	gra.noStroke();
	let step = min(gra.width,gra.height)/Math.floor(random(5,10));
	let mode = random(3);
	for(let x = 0; x-step <= gra.width; x +=step)
	{
		for(let y = 0; y-step<= gra.height; y +=step)
		{
			gra.fill(random(255));
			if(mode < 1)gra.ellipse(x,y,step/2,step/2);
			else if(mode < 2)gra.rect(x,y,step/2,step/2);
			else
			{
				gra.rect(x,gra.height/2,step/20,height);
				gra.rect(gra.width/2,y,width,step/20);
			}
		}
	}
}

function createCols(_url) {
  let slash_index = _url.lastIndexOf('/');
  let pallate_str = _url.slice(slash_index + 1);
  let arr = pallate_str.split('-');
  for (let i = 0; i < arr.length; i++) {
    arr[i] = '#' + arr[i];
  }
  return arr;
}

function mousePressed(){
  save('pix.jpg');
}


// === Tab: Shader ===
var frag = `
// Title: FishEye Texture

#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;
uniform sampler2D u_img;
#define PI 3.14159265358979323846


float box(in vec2 _st, in vec2 _size){
    _size = vec2(0.5) - _size*0.5;
    vec2 uv = smoothstep(_size,
                        _size+vec2(0.001),
                        _st);
    uv *= smoothstep(_size,
                    _size+vec2(0.001),
                    vec2(1.0)-_st);
    return uv.x*uv.y;
}


mat2 rotate2d(float _angle)
{
    return mat2(cos(_angle),-sin(_angle),
                sin(_angle),cos(_angle));
}


vec3 grid(vec2 uv)
{
    float span = 0.1;
    vec2 uvf = mod(fract(uv/span),1.);
    float v = uvf.x > .99 && uvf.x <= 1.  ||  uvf.y > .99 && uvf.y <= 1. ? 1. : 0.;
    vec3 gra = vec3(uv.x,uv.y,0.);
    return vec3(gra.xy*1.,v);
}

void main() {
    vec2 uv = gl_FragCoord.xy/u_resolution.xy ;
    vec2 mouse = u_mouse/u_resolution.xy;
    uv = vec2(uv.x,1.-uv.y);//for p5


    vec2 vm = uv-mouse;
    float d = length(vm)*(4.0 +sin(u_time)*.5);
    d = pow(d,.9);
    d = smoothstep(0.,1.,d);
    vec2 r = d* vm;

    float rd = length(vm)*2.5;
    rd = pow(rd,.3);
    rd = 1.-smoothstep(0.,1.,rd);
    r = rotate2d((3.5 +sin(u_time*.5)*2.)*PI*(rd)) *r;
    r += mouse;

    //vec3 color =  grid(r) + vec3(box(r,vec2(.1)));
    vec3 color = texture2D(u_img,r).rgb;
    gl_FragColor = vec4(color,1.);
}
`;


var vert=`
//standard vertex shader
#ifdef GL_ES
      precision highp float;
    #endif
		#extension GL_OES_standard_derivatives : enable
    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;
    attribute vec4 aVertexColor;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec4 var_vertCol;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;

    void main() {
      gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);

      // just passing things through
      var_vertPos      = aPosition;
      var_vertCol      = aVertexColor;
      var_vertNormal   = aNormal;
      var_vertTexCoord = aTexCoord;
    }
`;

